/**
 * The undeclared fallback.
 *
 * Nothing said what this result means, so the card does not pretend to know.
 * One line stating what came back, with the fields one click away. Guessing a
 * headline or promoting a "probably the answer" field is how a renderer makes
 * an arbitrary bag look intentional — and every hour spent perfecting that is
 * an hour that makes declaring a template less attractive.
 */
const UndeclaredResult: FC<{
	value: unknown;
	/** The caller's own heading, echoed back by the tool. Rendered, never dropped. */
	title?: string;
	openLink: (href: string) => void;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, title, openLink, viewState, onViewStateChange }) => {
	// A bare string or number is already its own summary — wrapping it in an
	// "N fields" line would state a field count it does not have. ValueView
	// already collapses one that runs long.
	if (value !== undefined && !isRecord(value)) {
		return (
			<ValueView
				value={value}
				openLink={openLink}
				stateKey="undeclared"
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	const fieldCount = isRecord(value) ? Object.keys(value).length : 0;
	const summary =
		fieldCount > 0
			? `${fieldCount} ${fieldCount === 1 ? "field" : "fields"}`
			: "No return value";
	const details = (
		<PersistentDetails
			summary={
				<span className="text-muted-foreground">
					<CheckCircle2 className="mr-1 inline h-3.5 w-3.5 text-green-600" />
					{summary}
				</span>
			}
			stateKey="details.undeclared-result.open"
			viewState={viewState}
			onViewStateChange={onViewStateChange}
			className="px-1 py-0.5 text-xs"
		>
			<div className="mt-2 text-foreground">
				<ValueView
					value={value}
					openLink={openLink}
					depth={1}
					stateKey="undeclared"
					viewState={viewState}
					onViewStateChange={onViewStateChange}
				/>
			</div>
		</PersistentDetails>
	);
	// The heading is the one thing the caller DID declare about this result, so
	// it is stated above the summary rather than destructured away. Dropping it
	// here was the same defect as dropping a query's title on the empty-result
	// path: a caller-supplied heading discarded on a secondary render path.
	if (!title) return details;
	return (
		<div>
			<h3 className="mb-1 font-medium text-sm">{title}</h3>
			{details}

