const GenericResult: FC<{
	value: UnknownRecord;
	openLink: (href: string) => void;
	viewState?: ViewState;
	onViewStateChange?: ViewStateChange;
}> = ({ value, openLink, viewState, onViewStateChange }) => {
	const declared = declaredTemplate(value);
	if (declared) {
		return (
			<DeclaredView
				declared={declared}
				value={value}
				openLink={openLink}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (isSearchMemoryResult(value)) {
		return (
			<SearchMemoryView
				value={value}
				openLink={openLink}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (isSaveReceipt(value)) {
		return (
			<SaveReceiptView
				value={value}
				openLink={openLink}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (hasPurposeCollections(value)) {
		return (
			<PurposeCollections
				value={value}
				openLink={openLink}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (looksLikeEvent(value)) {
		return (
			<EventView
				event={value}
				openLink={openLink}
				stateKey="result"
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (looksLikeEntity(value)) {
		return (
			<EntityView
				entity={value}
				openLink={openLink}
				stateKey="result"
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	const { title, ...body } = value;
	return (
		<UndeclaredResult
			value={body}
			title={
				typeof title === "string" && title.trim() ? title.trim() : undefined
			}
			openLink={openLink}
			viewState={viewState}
			onViewStateChange={onViewStateChange}
		/>
	);
};

