input.new_string:
/**
 * The run_sdk / query_sdk envelope, keyed on fields that survive the boundary.
 *
 * `toMcpPublicSdkScriptResult` (server `sdk_run.ts`) strips `logs`,
 * `sdk_call_trace` and every other diagnostic before a result reaches an MCP
 * client, so keying this on `logs` matched Lobu's own SPA and nothing else —
 * every ChatGPT card fell past this branch to the undeclared printer. `success`
 * and `dry_run` are set unconditionally on both shapes.
 */
function isSdkResult(value: UnknownRecord): boolean {
	return typeof value.success === "boolean" && typeof value.dry_run === "boolean";
}

/**
 * The outcome the reader asked about, which is not always the envelope's.
 *
 * `success: true` means the script finished. A command it dispatched can still
 * have failed — a non-zero exit two levels down under a green check reads as
 * "your tests passed". Only unambiguous signals count: an explicit exit code, a
 * timeout flag, a failed status, or a nested `success: false`.
 */
function nestedFailure(
	returnValue: unknown
): { label: string; meta?: string } | null {
	if (!isRecord(returnValue)) return null;
	const candidates = [returnValue, returnValue.output].filter(isRecord);
	for (const candidate of candidates) {
		if (candidate.timed_out === true) return { label: "Command timed out" };
		if (typeof candidate.exit_code === "number" && candidate.exit_code !== 0) {
			return { label: "Command failed", meta: `exit ${candidate.exit_code}` };
		}
		if (candidate.success === false) return { label: "Returned a failure" };
		if (candidate.status === "failed" || candidate.status === "error") {
			return { label: "Returned a failure", meta: String(candidate.status) };
		}
	}
	return null;
}

