/**
 * The shape an MCP client actually receives: `toMcpPublicSdkScriptResult`
 * (server `sdk_run.ts`) strips `logs`, `sdk_call_trace`, `sdk_calls` and
 * `duration_ms` from every run_sdk / query_sdk result. Every fixture above
 * carries `logs`, which is why this whole branch could be dead in ChatGPT while
 * the suite stayed green.
 */
describe("MCP-public SDK envelope", () => {
	const publicEnvelope = (extra: Record<string, unknown>) => ({
		success: true,
		skipped_calls: 0,
		side_effect_preview: [],
		dry_run: false,
		...extra,
	});

	it("renders the SDK card, not the undeclared field dump", () => {
		render(
			<McpResultView
				toolName="run_sdk"
				value={publicEnvelope({ return_value: { rows: [{ id: 1 }] } })}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		expect(screen.getByText("Completed")).toBeInTheDocument();
		// The envelope's own transport fields are never the answer.
		expect(screen.queryByText("Skipped Calls")).not.toBeInTheDocument();
		expect(screen.queryByText("Dry Run")).not.toBeInTheDocument();
	});

	it("omits the duration the public shape does not carry", () => {
		render(
			<McpResultView
				toolName="run_sdk"
				value={publicEnvelope({ return_value: { ok: true } })}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		expect(screen.queryByText(/0 ms/)).not.toBeInTheDocument();
	});

	it("states the nested failure instead of a green check over exit 1", () => {
		render(
			<McpResultView
				toolName="run_sdk"
				value={publicEnvelope({
					return_value: {
						action: "execute",
						run_id: 948606,
						status: "completed",
						output: {
							success: false,
							exit_code: 1,
							timed_out: false,
							duration_ms: 4932,
							operation_key: "run",
						},
					},
				})}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		expect(screen.getByText("Command failed")).toBeInTheDocument();
		expect(screen.getByText(/exit 1/)).toBeInTheDocument();
		expect(screen.queryByText("Completed")).not.toBeInTheDocument();
		expect(
			screen.getByText("The script itself ran to completion."),
		).toBeInTheDocument();
	});

	it("reports a timed-out command as a timeout, not a success", () => {
		render(
			<McpResultView
				toolName="run_sdk"
				value={publicEnvelope({
					return_value: { output: { timed_out: true, exit_code: 0 } },
				})}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		expect(screen.getByText("Command timed out")).toBeInTheDocument();
	});

	it("keeps the green check when nothing nested reports a failure", () => {
		render(
			<McpResultView
				toolName="run_sdk"
				value={publicEnvelope({
					return_value: { output: { exit_code: 0, success: true } },
				})}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
