import { fireEvent, render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { McpResultView } from "./result-view";

/**
 * Matrix of default-collapse behavior for arbitrary result shapes.
 * Purpose collections / SQL already had toggles; this locks the generic path.
 */

const longError =
	"Unknown table 'information_schema.tables' — not in the queryable allowlist, so the query did not run. Queryable tables are: entities, events, behaviors.";

function sdkEnvelope(returnValue: unknown) {
	return {
		success: true as const,
		return_value: returnValue,
		logs: [] as unknown[],
		duration_ms: 10,
		sdk_calls: 1,
		sdk_call_trace: [] as unknown[],
		side_effect_preview: [] as unknown[],
		dry_run: false,
	};
}

// queryAll, not getAll: a result with nothing to disclose renders no buttons at
// all, and getAllByRole throws on an empty match.
function collapsedButtons() {
	return screen
		.queryAllByRole("button")
		.filter((button) => button.getAttribute("aria-expanded") === "false");
}

function expandedButtons() {
	return screen
		.queryAllByRole("button")
		.filter((button) => button.getAttribute("aria-expanded") === "true");
}

/**
 * Every undeclared return draws one summary line instead of a card, so open it
 * first — the collapse rule under test applies one click in.
 */
function openThinResult(): boolean {
	// PersistentDetails prefixes the caret glyph, so match the tail, not the whole.
	const thin = collapsedButtons().find((button) =>
		/(^|\s|▸)(\d+ fields?|No return value)\s*$/.test(button.textContent ?? ""),
	);
	if (!thin) return false;
	fireEvent.click(thin);
	return true;
}

describe("MCP result default collapse matrix", () => {
	it.each([
		{
			name: "allowlist-style diagnostic keys",
			value: sdkEnvelope({
				EntityTypes: null,
				Tables: longError,
				ok: true,
			}),
			// Nothing declared what this bag means, so nothing is promoted: the
			// long string collapses like any other bulky field.
			expectVisible: ["EntityTypes", "null", "Ok", "true"],
			expectCollapsed: [/Tables · Unknown table/],
			expectHidden: [longError],
		},
		{
			name: "deep nested config",
			value: sdkEnvelope({
				status: "ok",
				config: {
					region: "us-east",
					limits: { max_rows: 500 },
				},
			}),
			expectVisible: ["Status", "ok"],
			expectCollapsed: [/Config · 2 fields/],
			expectHidden: ["us-east", "500"],
		},
		{
			name: "array under arbitrary key",
			value: sdkEnvelope({
				label: "batch",
				items: Array.from({ length: 12 }, (_, i) => ({
					id: i + 1,
					name: `row-${i + 1}`,
				})),
			}),
			expectVisible: ["Label", "batch"],
			expectCollapsed: [/Items · 12 items/],
			expectHidden: ["row-1", "row-12"],
		},
		{
			name: "multiline string field",
			value: sdkEnvelope({
				title: "Report",
				body: "Line one of the report.\nLine two with more detail.\nLine three wraps the story.",
			}),
			expectVisible: ["Title", "Report"],
			expectCollapsed: [/Body · Line one of the report/],
			expectHidden: [
				"Line one of the report.\nLine two with more detail.\nLine three wraps the story.",
			],
		},
		{
			name: "bare top-level object (no SDK envelope)",
			value: {
				ready: true,
				payload: { ids: [1, 2, 3], meta: { source: "agent" } },
				message: "done",
			},
			expectVisible: ["Ready", "true", "Message", "done"],
			expectCollapsed: [/Payload · 2 fields/],
			expectHidden: ["agent"],
		},
		{
			name: "empty array and empty object fields",
			value: sdkEnvelope({
				rows_empty: [],
				object_empty: {},
				flag: false,
			}),
			// Empty structures are stated, not hidden — a disclosure that opens on
			// nothing is worse than the one line it replaces.
			expectVisible: ["Flag", "false", "Rows Empty", "Object Empty"],
			expectCollapsed: [],
			expectHidden: [],
		},
	])("collapses bulky fields for $name", ({
		value,
		expectVisible,
		expectCollapsed,
		expectHidden,
	}) => {
		render(
			<McpResultView
				value={value}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);
		const wasThin = openThinResult();

		for (const text of expectVisible) {
			expect(screen.getByText(text)).toBeInTheDocument();
		}
		for (const name of expectCollapsed) {
			const button = screen.getByRole("button", { name });
			expect(button).toHaveAttribute("aria-expanded", "false");
		}
		for (const text of expectHidden) {
			expect(screen.queryByText(text)).not.toBeInTheDocument();
		}
		// Debug is off; the undeclared summary line is the only disclosure open.
		expect(expandedButtons().length).toBe(wasThin ? 1 : 0);
	});

	it("expands nested levels one at a time", () => {
		render(
			<McpResultView
				value={sdkEnvelope({
					outer: { mid: { leaf: "secret-value" } },
				})}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		openThinResult();
		expect(screen.queryByText("secret-value")).not.toBeInTheDocument();
		fireEvent.click(screen.getByRole("button", { name: /Outer · 1 field/ }));
		expect(screen.queryByText("secret-value")).not.toBeInTheDocument();
		fireEvent.click(screen.getByRole("button", { name: /Mid · 1 field/ }));
		expect(screen.getByText("Leaf")).toBeInTheDocument();
		expect(screen.getByText("secret-value")).toBeInTheDocument();
	});

	it("collapses a long top-level return string", () => {
		const long =
			"This entire return is one long diagnostic string that should not paint the full card open by default because it exceeds the short scalar character budget used for inline display.";
		render(
			<McpResultView
				value={sdkEnvelope(long)}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		expect(screen.queryByText(long)).not.toBeInTheDocument();
		const [toggle] = collapsedButtons().filter((button) =>
			(button.textContent ?? "").includes("This entire return"),
		);
		expect(toggle).toBeDefined();
		fireEvent.click(toggle);
		expect(screen.getByText(long)).toBeInTheDocument();
	});

	it("keeps purpose collections collapsed and short siblings visible", () => {
		const longBlob =
			"Internal trace that is long enough to collapse beside purpose collections and must not dump into the card by default.";
		render(
			<McpResultView
				value={sdkEnvelope({
					entities: [
						{
							id: 41,
							name: "Northwind",
							entity_type: "company",
							metadata: { stage: "customer" },
						},
					],
					summary: "1 company matched",
					total: 1,
					debug_blob: longBlob,
				})}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);

		expect(
			screen.getByRole("button", { name: /Found entities · 1 item/ }),
		).toHaveAttribute("aria-expanded", "false");
		expect(screen.queryByText("Northwind")).not.toBeInTheDocument();
		expect(screen.getByText("Summary")).toBeInTheDocument();
		expect(screen.getByText("1 company matched")).toBeInTheDocument();
		expect(screen.getByText("Total")).toBeInTheDocument();
		expect(screen.getByText("1")).toBeInTheDocument();
		expect(
			screen.getByRole("button", { name: /Debug Blob · Internal trace/ }),
		).toHaveAttribute("aria-expanded", "false");
		expect(screen.queryByText(longBlob)).not.toBeInTheDocument();

		fireEvent.click(
			screen.getByRole("button", { name: /Found entities · 1 item/ }),
		);
		expect(screen.getByText("Northwind")).toBeInTheDocument();
		fireEvent.click(
			screen.getByRole("button", { name: /Debug Blob · Internal trace/ }),
		);
		expect(screen.getByText(longBlob)).toBeInTheDocument();
	});

	it("states empty collections inline instead of behind a toggle", () => {
		render(
			<McpResultView
				value={sdkEnvelope({ rows_empty: [], meta_empty: {}, flag: false })}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);
		openThinResult();
		// A `Rows Empty · 0 items` disclosure is a control that reveals nothing:
		// opening it costs a click to learn what the summary already stated.
		expect(collapsedButtons()).toHaveLength(0);
		expect(screen.getByText("Rows Empty")).toBeInTheDocument();
		expect(screen.getByText("Meta Empty")).toBeInTheDocument();
		expect(screen.getAllByText("None")).toHaveLength(2);
		expect(screen.getByText("Flag")).toBeInTheDocument();
		expect(screen.getByText("false")).toBeInTheDocument();
	});

	it("purpose SQL path still collapses rows by default", () => {
		render(
			<McpResultView
				toolName="query_sql"
				value={{
					sql: "SELECT 1",
					rows: [{ id: 1 }],
					columns: [{ name: "id", type: "integer" }],
					total_count: 1,
					has_more: false,
					execution_time_ms: 1,
				}}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);
		const toggle = screen.getByRole("button", { name: /\d row(s)? ·/i });
		expect(toggle).toHaveAttribute("aria-expanded", "false");
		// Table body is not mounted while collapsed (summary may still mention counts).
		expect(document.querySelector("table")).toBeNull();
		fireEvent.click(toggle);
		expect(document.querySelector("table")).not.toBeNull();
	});

	it("short URL scalars stay inline (not collapsed)", () => {
		render(
			<McpResultView
				value={sdkEnvelope({
					link: "https://example.com/x",
					note: "ok",
				})}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
			/>,
		);
		openThinResult();
		expect(screen.getByText("Link")).toBeInTheDocument();
		expect(screen.getByText("example.com/x")).toBeInTheDocument();
		expect(screen.getByText("ok")).toBeInTheDocument();
		expect(collapsedButtons().length).toBe(0);
	});
});

