content.content:
					pageSize={MCP_TABLE_PAGE_SIZE}
					rows={records}
					openLink={openLink}
					stateKey={`${stateKey}.table`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
					renderStructuredValue={(value, link) => (
						<ValueView value={value} openLink={link} depth={1} />
					)}
				/>
			);
		}
		return (
			<ValueList
				values={value}
				openLink={openLink}
				depth={depth}
				stateKey={stateKey}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	}
	if (!isRecord(value))
		return <span className="text-sm">Unsupported value</span>;
	if (looksLikeEvent(value))
		return (
			<EventView
				event={value}
				openLink={openLink}
				stateKey={stateKey}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	if (looksLikeEntity(value))
		return (
			<EntityView
				entity={value}
				openLink={openLink}
				stateKey={stateKey}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
			/>
		);
	// Generic objects: short scalars stay inline; arrays, nested objects, and
	// long / multi-line strings collapse behind a toggle (same default as
	// purpose collections / SQL). Arbitrary SDK returns must not dump open.
	// A 200-key return laid out 200 rows. Bounding the DEFAULT is the point —
	// the overflow still has to be reachable, or the card silently drops data
	// with nowhere to send the reader. So: first 20 inline, the rest one click
	// away, nothing lost.
	const allEntries = Object.entries(value);
	const shownEntries = allEntries.slice(0, GENERIC_FIELD_LIMIT);
	const overflowEntries = allEntries.slice(GENERIC_FIELD_LIMIT);
	const renderEntry = ([key, inner]: [string, unknown]) => {
		if (isInlineValue(inner)) {
			return (
				<div
					key={key}
					className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-2 text-xs"
				>
					<span className="break-words font-medium text-muted-foreground">
						{humanize(key)}
					</span>
					<span className="min-w-0">
						{typeof inner === "string" ? (
							<LinkValue value={inner} openLink={openLink} />
						) : (
							<span
								className={
									isEmptyStructure(inner)
										? "text-muted-foreground text-sm"
										: "break-words text-sm"
								}
							>
								{inlineText(inner)}
							</span>
						)}
					</span>
				</div>
			);
		}
		return (
			<PersistentDetails
				key={key}
				summary={fieldSummary(key, inner)}
				stateKey={`${stateKey}.${key}.open`}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
				className="text-xs text-muted-foreground"
			>
				<div className="mt-2 text-foreground">
					{typeof inner === "string" ? (
						<p className="whitespace-pre-wrap break-words text-sm">{inner}</p>
					) : (
						<ValueView
							value={inner}
							openLink={openLink}
							depth={depth + 1}
							stateKey={`${stateKey}.${key}`}
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						/>
					)}
				</div>
			</PersistentDetails>
		);
	};
	return (
		<div className="space-y-1.5">
			{shownEntries.map(renderEntry)}
			{overflowEntries.length > 0 ? (
				<PersistentDetails
					summary={`${overflowEntries.length} more ${
						overflowEntries.length === 1 ? "field" : "fields"
					}`}
					stateKey={`${stateKey}.overflow.open`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
					className="text-muted-foreground text-xs"
				>
					<div className="mt-1.5 space-y-1.5 text-foreground">
						{overflowEntries.map(renderEntry)}
					</div>
				</PersistentDetails>
			) : null}
		</div>
	);
};

