/** Keep short scalars always visible; everything else is collapsed by default. */
const SHORT_SCALAR_LIMIT = 90;

function isShortScalar(value: unknown): boolean {
	if (
		value === null ||
		typeof value === "number" ||
		typeof value === "boolean"
	) {
		return true;
	}
	if (typeof value === "string") {
		return value.length <= SHORT_SCALAR_LIMIT && !value.includes("\n");
	}
	return false;
}

/** An array or object with nothing in it. */
function isEmptyStructure(value: unknown): boolean {
	if (Array.isArray(value)) return value.length === 0;
	return isRecord(value) && Object.keys(value).length === 0;
}

/**
 * What can be stated on one line rather than hidden behind a disclosure.
 *
 * Empty arrays and objects belong here even though they are structures: a
 * `Rows · 0 items` toggle is a control that reveals nothing when opened, so it
 * costs the reader a click to learn what the summary already said.
 */
function isInlineValue(value: unknown): boolean {
	return isShortScalar(value) || isEmptyStructure(value);
}

/** How an inline value reads in the value column. */
function inlineText(value: unknown): string {
	if (Array.isArray(value)) return "None";
	if (isRecord(value)) return "None";
	return compactValue(value);
}

function fieldSummary(key: string, value: unknown): string {
	const label = humanize(key);
	if (Array.isArray(value)) {
		const n = value.length;
		return `${label} · ${n} ${n === 1 ? "item" : "items"}`;
	}
	if (isRecord(value)) {
		const n = Object.keys(value).length;
		return `${label} · ${n} ${n === 1 ? "field" : "fields"}`;
	}
	if (typeof value === "string") {
		// Prefer the first line only — joining the whole multi-line blob into the
		// summary would leak later lines while the section is still collapsed.
		const firstLine = (value.split(/\r?\n/, 1)[0] ?? "")
			.replace(/\s+/g, " ")
			.trim();
		if (!firstLine) return label;
		const preview =
			firstLine.length > 60 ? `${firstLine.slice(0, 60)}…` : firstLine;
		return `${label} · ${preview}`;
	}
	return label;
}

const ValueView: FC<{
	value: unknown;
	openLink: (href: string) => void;
	depth?: number;

input.old_string:
	// Generic objects: short scalars stay inline; arrays, nested objects, and
	// long / multi-line strings collapse behind a toggle (same default as
	// purpose collections / SQL). Arbitrary SDK returns must not dump open.
	// A 200-key return laid out 200 rows. Bounding the DEFAULT is the point —
	// the overflow still has to be reachable, or the card silently drops data
	// with nowhere to send the reader. So: first 20 inline, the rest one click
	// away, nothing lost.
	const allEntries = Object.entries(value);
	const shownEntries = allEntries.slice(0, GENERIC_FIELD_LIMIT);
	const overflowEntries = allEntries.slice(GENERIC_FIELD_LIMIT);
	const renderEntry = ([key, inner]: [string, unknown]) => {
		if (isInlineValue(inner)) {
			return (
				<div
					key={key}
					className="grid grid-cols-[minmax(6rem,0.35fr)_1fr] gap-2 text-xs"
				>
					<span className="break-words font-medium text-muted-foreground">
						{humanize(key)}
					</span>
					<span className="min-w-0">
						{typeof inner === "string" ? (
							<LinkValue value={inner} openLink={openLink} />
						) : (
							<span
								className={
									isEmptyStructure(inner)
										? "text-muted-foreground text-sm"
										: "break-words text-sm"
								}
							>
								{inlineText(inner)}
							</span>
						)}
					</span>
				</div>
			);
		}
		return (
			<PersistentDetails
				key={key}
				summary={fieldSummary(key, inner)}
				stateKey={`${stateKey}.${key}.open`}
				viewState={viewState}
				onViewStateChange={onViewStateChange}
				className="text-xs text-muted-foreground"
			>
				<div className="mt-2 text-foreground">
					{typeof inner === "string" ? (
						<p className="whitespace-pre-wrap break-words text-sm">{inner}</p>
					) : (
						<ValueView
							value={inner}
							openLink={openLink}
							depth={depth + 1}
							stateKey={`${stateKey}.${key}`}
							viewState={viewState}
							onViewStateChange={onViewStateChange}
						/>
					)}
				</div>
			</PersistentDetails>
		);
	};
	return (
		<div className="space-y-1.5">
			{shownEntries.map(renderEntry)}
			{overflowEntries.length > 0 ? (
				<PersistentDetails
					summary={`${overflowEntries.length} more ${
						overflowEntries.length === 1 ? "field" : "fields"
					}`}
					stateKey={`${stateKey}.overflow.open`}
					viewState={viewState}
					onViewStateChange={onViewStateChange}
					className="text-muted-foreground text-xs"
				>
					<div className="mt-1.5 space-y-1.5 text-foreground">
						{overflowEntries.map(renderEntry)}
					</div>
				</PersistentDetails>
			) : null}
		</div>
	);
};

input.new_string:
	// Nothing recognized this object, so it is rendered as what it is. The
	// previous treatment — humanized keys, one disclosure per field, recursion
	// into every nested level — dressed an arbitrary bag as a designed table:
	// `Timed Out`, `Operation Key`, `Return Value · 4 fields · Output · 7 fields`
	// are JSON keys wearing title case, and the shape they implied was never
	// chosen by anyone. JSON is honest about that, and it makes declaring a
	// template the way to get a card rather than one more inference to tune.
	return <RawValue value={value} />;
};

/** Longest JSON a card will show before sending the reader to Lobu for the rest. */
const RAW_VALUE_LIMIT = 4000;

const RawValue: FC<{ value: unknown }> = ({ value }) => {
	const text = stringify(value);
	const clipped = text.length > RAW_VALUE_LIMIT;
	return (
		<div className="space-y-1">
			<pre className="max-h-80 overflow-auto whitespace-pre-wrap break-words rounded-md bg-muted/40 p-2 font-mono text-xs">
				{clipped ? `${text.slice(0, RAW_VALUE_LIMIT)}…` : text}
			</pre>
			{clipped ? (
				<p className="text-muted-foreground text-xs">
					Showing the first {RAW_VALUE_LIMIT.toLocaleString()} characters of{" "}
					{text.length.toLocaleString()}. Open the run in Lobu for the rest.
				</p>
			) : null}
		</div>
	);
};

