/** Longest JSON a card will show before sending the reader to Lobu for the rest. */
const RAW_VALUE_LIMIT = 4000;

const RawValue: FC<{ value: unknown }> = ({ value }) => {
	const text = stringify(value);
	const clipped = text.length > RAW_VALUE_LIMIT;
	return (
		<div className="space-y-1">
			<pre className="max-h-80 overflow-auto whitespace-pre-wrap break-words rounded-md bg-muted/40 p-2 font-mono text-xs">
				{clipped ? `${text.slice(0, RAW_VALUE_LIMIT)}…` : text}
			</pre>
			{clipped ? (
				<p className="text-muted-foreground text-xs">
					Showing the first {RAW_VALUE_LIMIT.toLocaleString()} characters of{" "}
					{text.length.toLocaleString()}. Open the run in Lobu for the rest.
				</p>
			) : null}
		</div>
	);
};

