/**
 * A `payload_type: "media"` event's payload — caption and a brokered link.
 *
 * The payload_type union is closed (`text | markdown | json_template | media |
 * empty`, core `protocol.ts`), and media was the one member with no branch, so
 * it fell to the generic printer. The card never inlines remote images (the
 * markdown renderer strips them for the same reason), so the link is the
 * affordance; anything the shape did not declare stays visible as JSON rather
 * than being dropped.
 */
const MediaPayload: FC<{
	data: UnknownRecord;
	openLink: (href: string) => void;
