it("keeps every field of a wide undeclared object reachable", () => {
	// Bounding the default is the point; discarding the remainder is not.
	// The 21st field must be one click away, not gone.
	const wide = Object.fromEntries(
		Array.from({ length: 26 }, (_, i) => [`key_${i + 1}`, `value ${i + 1}`]),
	);
	render(
		<McpResultView
			value={wide}
			onAction={() => undefined}
			openLink={() => undefined}
			canViewDebug={false}
		/>,
	);
	fireEvent.click(screen.getByRole("button", { name: /26 fields/ }));
	expect(screen.getByText("value 1")).toBeInTheDocument();
	expect(screen.queryByText("value 26")).not.toBeInTheDocument();
	fireEvent.click(screen.getByRole("button", { name: /6 more fields/ }));
	expect(screen.getByText("value 26")).toBeInTheDocument();
});

it("does not share one overflow disclosure across sibling wide objects", () => {
	// The overflow key was a constant, so every nested wide object persisted to
	// the same slot. Reproducing it needs a host that genuinely ECHOES state
	// back as a new prop — mutating one object in place never re-renders, and
	// each disclosure then falls through to its own local state, hiding the
	// collision entirely.
	const wide = (tag: string) =>
		Object.fromEntries(
			Array.from({ length: 24 }, (_, i) => [`k${i + 1}`, `${tag}-${i + 1}`]),
		);
	const Host = () => {
		const [viewState, setViewState] = useState<Record<string, boolean>>({});
		return (
			<McpResultView
				value={{ first: wide("a"), second: wide("b") }}
				onAction={() => undefined}
				openLink={() => undefined}
				canViewDebug={false}
				viewState={viewState}
				onViewStateChange={(key, next) =>
					setViewState((prev) => ({ ...prev, [key]: next as boolean }))
				}
			/>
		);
	};
	render(<Host />);
	fireEvent.click(screen.getByRole("button", { name: /2 fields/ }));
	fireEvent.click(screen.getByRole("button", { name: /^First · 24 fields/ }));
	fireEvent.click(
		screen.getByRole("button", { name: /^Second · 24 fields/ }),
	);
	const overflows = screen.getAllByRole("button", { name: /4 more fields/ });
	expect(overflows).toHaveLength(2);
	fireEvent.click(overflows[0]);
	expect(
		screen
			.getAllByRole("button", { name: /4 more fields/ })
			.filter((b) => b.getAttribute("aria-expanded") === "true"),
	).toHaveLength(1);
});

