it("resets disclosure and list pagination when result state is cleared", async () => {
	const value = {
		items: Array.from({ length: 11 }, (_, index) => `item-${index + 1}`),
	};
	const { rerender } = render(
		<McpResultView
			value={value}
			viewState={{
				"details.debug.open": true,
				"details.undeclared-result.open": true,
				"undeclared.items.open": true,
				"undeclared.items.page": 1,
			}}
			onViewStateChange={() => undefined}
			onAction={() => undefined}
			openLink={() => undefined}
		/>,
	);
	expect(screen.getByText("item-11")).toBeInTheDocument();
	expect(screen.getByText("2 / 2")).toBeInTheDocument();
	expect(
		screen.getByRole("button", { name: "Copy JSON" }),
	).toBeInTheDocument();

	rerender(
		<McpResultView
			value={value}
			viewState={{}}
			onViewStateChange={() => undefined}
			onAction={() => undefined}
			openLink={() => undefined}
		/>,
	);

	// Generic arrays collapse by default; disclosure + page reset together.
	await waitFor(() =>
		expect(screen.getByRole("button", { name: /1 field/ })).toHaveAttribute(
			"aria-expanded",
			"false",
		),
	);
	fireEvent.click(screen.getByRole("button", { name: /1 field/ }));
	expect(
		screen.getByRole("button", { name: /Items · 11 items/ }),
	).toHaveAttribute("aria-expanded", "false");
	expect(screen.queryByText("item-11")).not.toBeInTheDocument();
	expect(screen.queryByText("item-1")).not.toBeInTheDocument();
	expect(
		screen.queryByRole("button", { name: "Copy JSON" }),
	).not.toBeInTheDocument();

	fireEvent.click(screen.getByRole("button", { name: /Items · 11 items/ }));
	expect(screen.getByText("item-1")).toBeInTheDocument();
	expect(screen.getByText("1 / 2")).toBeInTheDocument();
	expect(screen.queryByText("item-11")).not.toBeInTheDocument();
});

