/** How deep the prose split looks; a captured log sits at `output.stderr`. */
const TEXT_FIELD_DEPTH = 3;
/** Enough for stdout + stderr and their neighbours, not a wall of blocks. */
const TEXT_FIELD_LIMIT = 4;

/**
 * Split an unrecognized object into structure and prose.
 *
 * Escaping a captured `stderr` into a JSON string literal turns the one
 * readable thing in the payload into a single line of `\n`, so long and
 * multi-line strings are lifted out — labelled by the path that named them —
 * and the rest stays JSON. Arrays are left whole: an element has no name to
 * label a block with.
 */
function splitProse(
	value: UnknownRecord,
	depth = 0,
	prefix = "",
): { rest: unknown; text: Array<[string, string]> } {
	const rest: UnknownRecord = {};
	const text: Array<[string, string]> = [];
	for (const [key, inner] of Object.entries(value)) {
		const path = prefix ? `${prefix}.${key}` : key;
		if (typeof inner === "string" && !isShortScalar(inner)) {
			text.push([path, inner]);
			continue;
		}
		if (isRecord(inner) && depth < TEXT_FIELD_DEPTH) {
			const nested = splitProse(inner, depth + 1, path);
			text.push(...nested.text);
			rest[key] = nested.rest;
			continue;
		}
		rest[key] = inner;
	}
	return { rest, text };
}

const RawValue: FC<{ value: unknown }> = ({ value }) => {
	if (!isRecord(value)) return <RawBlock text={stringify(value)} />;
	const { rest, text } = splitProse(value);
	if (text.length === 0) return <RawBlock text={stringify(value)} />;
	const shown = text.slice(0, TEXT_FIELD_LIMIT);
	// Over the block budget, the remainder goes back into the JSON rather than
	// disappearing — a card that silently drops a field is the failure this
	// whole change is about.
	const structure =
		text.length > shown.length
			? {
					...(rest as UnknownRecord),
					...Object.fromEntries(text.slice(TEXT_FIELD_LIMIT)),
				}
			: rest;
	return (
		<div className="space-y-2">
			{Object.keys(structure as UnknownRecord).length > 0 ? (
				<RawBlock text={stringify(structure)} />
			) : null}
			{shown.map(([key, inner]) => (
				<RawBlock key={key} label={key} text={inner} />
			))}
		</div>
	);
};

