import { createServer } from "node:http";
import { writeFileSync } from "node:fs";

// Receives base64 data URLs POSTed from the browser so screenshots never enter
// the agent context. Text/plain body keeps it a CORS simple request.
createServer((req, res) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Headers", "*");
  if (req.method === "OPTIONS") return res.end();
  const name = new URL(req.url, "http://x").searchParams.get("name") || "shot";
  let body = "";
  req.on("data", (chunk) => (body += chunk));
  req.on("end", () => {
    try {
      const url = JSON.parse(body);
      const base64 = String(url).split(",")[1] ?? "";
      writeFileSync(`${process.env.SHOT_DIR}/${name}.png`, Buffer.from(base64, "base64"));
      console.log(`saved ${name} (${base64.length} b64 chars)`);
      res.end("ok");
    } catch (error) {
      console.log(`failed ${name}: ${error.message}`);
      res.statusCode = 500;
      res.end("err");
    }
  });
}).listen(5200, "127.0.0.1", () => console.log("receiver on 5200"));

