	const previousHostIdentity =
		previousId === null || toolCallName.current === null
			? null
			: hostIdentityKey(previousId, toolCallName.current);
	if (
		hasDetachedAppResult.current &&
		supersededIdentity === null &&
		previousHostIdentity === null
	) {
		// An app action can complete before the host publishes the originating
		// card identity. The first late identity is not evidence of a new card;
		// remember it so a subsequent different identity remains a hard boundary.
		supersededHostIdentity.current = nextHostIdentity;
		return;
	}
	const identityChanged =
		toolCallId.current !== info.id || toolCallName.current !== info.name;
	const switchedCards =
		switchedFromDetachedAppResult ||
		switchedFromExplicitClear ||
		(previousHostIdentity !== null &&
			previousHostIdentity !== nextHostIdentity);
	supersededHostIdentity.current = null;
	if (switchedCards) {
		// Host card ids are result identities. A reused iframe must not carry
		// data, capabilities, or UI state from the previous card into the next.
		resetCurrentResult();
	}
	toolCallId.current = info.id;
	toolCallName.current = info.name;
	setToolName(info.name);
	if (switchedCards) persistOpenAiData(compatTargets, null);
	if (identityChanged) {
		if (switchedCards) {
