    let opened = 0;
    for (const button of panel) {
      const label = (button.textContent || '').toLowerCase();
      if (button.getAttribute('aria-expanded') === 'false' && !label.includes('debug')) {
        button.click();
        opened += 1;
      }
    }
    setTimeout(() => {
      const card = document.querySelector('main') || document.body;
      resolve(opened + ' opened :: ' + card.innerText.replace(/\\s+/g, ' ').slice(0, 400));
    }, 600);
  }, 3200))`;

  const report = [];
  let tab = null;
  for (const name of cases) {
    const url = `${base}?case=${name}`;
    const nav = await exec("navigate", tab ? { tab_id: tab, url } : { url, window_width: 1280 });
    if (!tab) tab = nav?.output?.tab_id ?? val(nav)?.tab_id;
    const probe = await exec("evaluate", { tab_id: tab, expression: OPEN_AND_READ });
    const shot = await exec("screenshot", { tab_id: tab });
    const dataUrl = findDataUrl(shot);
    let post = "no-image";
    if (dataUrl) {
      const send = await exec("evaluate", {
        tab_id: tab,
        expression: `fetch('http://127.0.0.1:5200/?name=${phase}-${name}',{method:'POST',body:${JSON.stringify(JSON.stringify(dataUrl))}}).then((r) => 'post=' + r.status)`,
      });
      post = val(send);
    }
    report.push({ case: name, post, text: val(probe) });
  }
  return { phase, report };
};
