/** How much of a text block a card shows before the reader asks for the rest. */
const RAW_VALUE_LIMIT = 4000;

/**
 * One verbatim block: a JSON structure, or a string lifted out of one.
 *
 * Long values open clipped, because a 200 KB stdout should not be the first
 * thing a card puts on screen. The tail is one click away rather than gone —
 * an MCP client has no other view of this result, and Debug is owner/admin
 * only, so discarding the remainder would leave a member no path to it.
 */
const RawBlock: FC<{ text: string; label?: string }> = ({ text, label }) => {
	const [expanded, setExpanded] = useState(false);
	const clipped = text.length > RAW_VALUE_LIMIT && !expanded;
	return (
		<div className="space-y-1">
			{label ? (
				<div className="font-mono text-muted-foreground text-xs">{label}</div>
			) : null}
			<pre className="max-h-80 overflow-auto whitespace-pre-wrap break-words rounded-md bg-muted/40 p-2 font-mono text-xs">
				{clipped ? `${text.slice(0, RAW_VALUE_LIMIT)}…` : text}
			</pre>
			{text.length > RAW_VALUE_LIMIT ? (
				<button
					type="button"
					className="text-muted-foreground text-xs underline underline-offset-2 hover:text-foreground"
					onClick={() => setExpanded(!expanded)}
				>
					{clipped
						? `Show all ${text.length.toLocaleString()} characters`
						: `Show the first ${RAW_VALUE_LIMIT.toLocaleString()} characters`}
				</button>
			) : null}
		</div>
	);
};

