type ViewState = Record<string, boolean | number | string>;
type ReviewTheme = "system" | "light" | "dark";

/**
 * 1 — presentation was declared (json_template triple, or a server LobuView).
 * 2 — a shape the renderer knows: SQL rows, entities, events, a write receipt.
 * 3 — undeclared: one summary line, fields one click away.
 *
 * There is deliberately no fourth state. A renderer that tries to make an
 * arbitrary bag look intentional is competing with the declared path we want
 * producers to take.
 */
type ResultTier = 1 | 2 | 3;

interface ReviewCase {
	id: string;
	label: string;
	toolName: string;
	tier: ResultTier;
	description: string;
	value: unknown;
	initialViewState?: ViewState;
}

