 * Diagnostics the server removes before a run_sdk / query_sdk result reaches an
 * MCP client (`toMcpPublicSdkScriptResult`, server `sdk_run.ts`).
 *
 * SDK-envelope fixtures below are written in the sandbox's internal shape,
 * which is what Lobu's own SPA renders. This harness reviews the MCP card, so
 * it strips them by default — a fixture carrying `logs` sailed past a card gate
 * that keys on `logs`, leaving ChatGPT on the generic result path while the
 * harness stayed green. The toolbar toggle puts them back for reviewing the
 * SPA.
 */
const SERVER_STRIPPED_KEYS = [
	"logs",
	"sdk_call_trace",
	"sdk_calls",
	"duration_ms",
] as const;

function asMcpClientValue(toolName: string, value: unknown): unknown {
	if (toolName !== "run_sdk" && toolName !== "query_sdk") return value;
	if (!value || typeof value !== "object" || Array.isArray(value)) return value;
	const stripped = { ...(value as Record<string, unknown>) };
	for (const key of SERVER_STRIPPED_KEYS) delete stripped[key];
	return stripped;
}

/** Tools shown first in the review harness; everything else groups under Other. */
