import { cleanup, render } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";
import {
	asMcpClientValue,
	type ReviewCase,
	reviewCases,
	SERVER_STRIPPED_KEYS,
} from "../review/cases";
import { McpResultView } from "./result-view";

/**
 * The card must render the same thing whether or not the server stripped its
 * diagnostics.
 *
 * `toMcpPublicSdkScriptResult` (server `sdk_run.ts`) removes `logs`,
 * `sdk_call_trace`, `sdk_calls` and `duration_ms` from every run_sdk /
 * query_sdk result on its way to an MCP client. Twice now a card branch has
 * been keyed on one of those fields — `sdk_call_trace` in #825, `logs` in #827
 * — which makes the branch match Lobu's own SPA and nothing else. Both shipped
 * green: every fixture was written in the internal shape, so the dead branch
 * was the only one under test.
 *
 * This sweeps the whole fixture set through both shapes and requires the
 * rendered text to match. A predicate that reads a stripped field diverges
 * here no matter which field it is.
 */

/**
 * The two status-line segments the internal shape can carry and the public one
 * cannot: they are read straight off `duration_ms` and `sdk_calls`. Everything
 * else in the card is expected to be identical.
 */
const DIAGNOSTIC_SEGMENTS = /(\d[\d,]* ms|\d[\d,]* SDK calls?)/g;

function textFor(reviewCase: ReviewCase, value: unknown): string {
	const { container } = render(
		<McpResultView
			value={value}
			toolName={reviewCase.toolName}
			viewState={reviewCase.initialViewState}
			onAction={() => undefined}
			openLink={() => undefined}
			canViewDebug={false}
		/>,
	);
	const text = (container.textContent ?? "")
		.replace(DIAGNOSTIC_SEGMENTS, "")
		// …and the separator that segment left behind.
		.replace(/·/g, "")
		.replace(/\s+/g, " ")
		.trim();
	cleanup();
	return text;
}

describe("Public and internal shapes render the same card", () => {
	const stripped = reviewCases.filter(
		(reviewCase) => asMcpClientValue(reviewCase.toolName, reviewCase.value) !== reviewCase.value,
	);

	// A sweep that silently matched nothing would pass forever. The fixture set
	// has to keep carrying diagnostics for this to be testing anything.
	it("covers the fixtures that carry server-only diagnostics", () => {
		expect(stripped.length).toBeGreaterThanOrEqual(5);
		const carried = new Set<string>();
		for (const reviewCase of stripped) {
			for (const key of SERVER_STRIPPED_KEYS) {
				if (Object.hasOwn(reviewCase.value as object, key)) carried.add(key);
			}
		}
		expect([...carried].sort()).toEqual([...SERVER_STRIPPED_KEYS].sort());
	});

	for (const reviewCase of stripped) {
		it(`${reviewCase.id} survives the public serializer`, () => {
			const internal = textFor(reviewCase, reviewCase.value);
			const publicShape = textFor(
				reviewCase,
				asMcpClientValue(reviewCase.toolName, reviewCase.value),
			);
			expect(publicShape).toBe(internal);
		});
	}
});

afterEach(cleanup);

