// Shared, DOM-free resolvers that read a metadata schema and decide how the
// built-in views (board / gallery) bind to its fields. Kept in one module so the
// list panel, the view templates, the registered components, and the tests all
// import the same logic (no drift between the auto-pick and what a view renders).

export interface WorkflowStateConfig {
	value: string;
	label?: string;
	terminal?: boolean;
	collapsed?: boolean;
	color?: string;
}

export interface WorkflowFieldConfig {
	field: string;
	states: WorkflowStateConfig[];
}

export interface RankFieldConfig {
	field: string;
}

export interface MetadataBoardProperty {
	description?: string;
	enum?: string[];
	"x-table-label"?: string;
	"x-lobu"?: {
		role?: string;
		states?: WorkflowStateConfig[];
	};
	"x-lobu-role"?: string;
	"x-image"?: boolean;
}

export interface BoardSchema {
	properties?: Record<string, MetadataBoardProperty>;
}

// Takes `unknown`: the workflow states below are derived from a schema `enum`,
// which JSON Schema does not require to hold strings. A numeric enum would
// otherwise reach `.replace` and throw, taking the whole view down rather than
// degrading one label.
function humanizeToken(value: unknown): string {
	return String(value ?? "")
		.replace(/[_-]+/g, " ")
		.replace(/\b\w/g, (c) => c.toUpperCase());
}

function workflowRole(prop: MetadataBoardProperty): string | undefined {
	return prop["x-lobu"]?.role || prop["x-lobu-role"];
}

export function resolveWorkflowField(
	schema?: BoardSchema,
): WorkflowFieldConfig | null {
	const properties = schema?.properties;
	if (!properties) return null;

	const entries = Object.entries(properties);
	// Board is opt-in only: a field must declare `x-lobu.role: "workflowState"`.
	// A field named status/state/stage with an enum is NOT a workflow column on
	// its own — it's just as likely a plain flag (members active/invited, a task
	// done/pending), so inferring a board from the key name mis-fires. Board is a
	// deliberate layout decision the schema declares, not a name heuristic.
	const explicit = entries.find(
		([, prop]) => workflowRole(prop) === "workflowState",
	);
	const match = explicit;
	if (!match) return null;

	const [field, prop] = match;
	const declaredStates = prop["x-lobu"]?.states;
	const states: WorkflowStateConfig[] =
		Array.isArray(declaredStates) && declaredStates.length > 0
			? declaredStates
			: (prop.enum ?? []).map((value) => ({ value }));
	if (states.length === 0) return null;

	return {
		field,
		states: states.map((state) => ({
			...state,
			label: state.label || humanizeToken(state.value),
			terminal:
				state.terminal ??
				["done", "complete", "completed", "closed", "archived"].includes(
					state.value.toLowerCase(),
				),
		})),
	};
}

export function resolveRankField(schema?: BoardSchema): RankFieldConfig | null {
	const properties = schema?.properties;
	if (!properties) return null;
	const entries = Object.entries(properties);
	const explicit = entries.find(
		([, prop]) => workflowRole(prop) === "sortRank",
	);
	const fallback = entries.find(([key]) =>
		["rank", "sort_rank", "order"].includes(key),
	);
	const match = explicit ?? fallback;
	return match ? { field: match[0] } : null;
}

interface MetadataGalleryProperty {
	description?: string;
	enum?: string[];
	format?: string;
	"x-table-label"?: string;
	"x-table-column"?: boolean;
	"x-image"?: boolean;
}

export interface GallerySchema {
	properties?: Record<string, MetadataGalleryProperty>;
}

/**
 * What the Gallery renders on each card. `hasImageField` gates the AUTO-PICK of
 * Gallery as a type's default view (a type with no image field shouldn't land
 * on a wall of monograms) — but a Gallery reached from the switcher still
 * renders monogram faces regardless, via `EntityAvatar initialsFallback`.
 */
export interface GalleryFieldConfig {
	/** True when the schema declares an `x-image` field. Drives auto-pick. */
	hasImageField: boolean;
	/** Optional subtitle field (the first meaningful string/enum column). */
	subtitleField?: string;
}

const IMAGE_FIELD_NAMES = new Set([
	"avatar",
	"photo",
	"image",
	"logo",
	"picture",
]);

function findImageField(schema: GallerySchema | undefined): string | undefined {
	const props = schema?.properties;
	if (!props) return undefined;
	// Explicit annotation wins; else a conventionally-named field.
	const annotated = Object.entries(props).find(([, p]) => p["x-image"])?.[0];
	if (annotated) return annotated;
	return Object.keys(props).find((k) => IMAGE_FIELD_NAMES.has(k.toLowerCase()));
}

/**
 * Resolve the Gallery config for a schema. Always returns a config (every type
 * can render as monograms); `hasImageField` reports whether the type is a
 * natural Gallery default. Returns null only for a schema with no properties at
 * all, where a gallery would be a grid of bare names.
 */
export function resolveGalleryFields(
	schema: GallerySchema | undefined,
): GalleryFieldConfig | null {
	const props = schema?.properties;
	if (!props || Object.keys(props).length === 0) return null;

	const imageField = findImageField(schema);
	// Pick a subtitle: the first non-image string/enum column, preferring ones
	// marked as table columns (the schema author's "this matters" signal).
	const candidates = Object.entries(props).filter(
		([key, p]) => key !== imageField && !p["x-image"],
	);
	const preferred =
		candidates.find(([, p]) => p["x-table-column"]) ?? candidates[0];

	return {
		hasImageField: !!imageField,
		subtitleField: preferred?.[0],
	};
}

